private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || headerPart.isEmpty() || end < 2) {
        return -1;
    }
    int limit = Math.min(end, headerPart.length() - 1);
    for (int i = 0; i < limit; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null) {
        return -1;
    }
    int len = headerPart.length();
    if (end < 0 || end >= len - 1) {
        return -1;
    }
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart==null||end<=0){return -1;}
    int max = Math.min(end, headerPart.length());
    for(int i=max-1;i>0;i--){
        char c = headerPart.charAt(i);
        if(c=='\n'){
            // prefer CRLF
            if(headerPart.charAt(i-1)=='\r'){
                return i-1;
            }
            return i;
        }
        if(c=='\r'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart==null){
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if(end<0 || end>headerPart.length()){
        throw new IllegalArgumentException("end index out of bounds");
    }
    int idx = headerPart.indexOf("\r\n", end);
    return idx >= 0 ? idx : -1;
}

private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds");
    }
    int i = end;
    while (i < headerPart.length() - 1) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
        i++;
    }
    return -1;
}

