@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    // Add all vertices to the graph
    for (V vertex : resultMap.values()) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }
    // Build edges between every pair of distinct vertices
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    for (int i = 0; i < n; i++) {
        V v1 = vertices.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = vertices.get(j);
            // Ensure we don't duplicate an existing edge
            if (!target.containsEdge(v1, v2) && !target.containsEdge(v2, v1)) {
                target.addEdge(v1, v2);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph must not be null");
    }
    if (resultMap == null || resultMap.isEmpty()) {
        return;
    }
    // Collect all vertices from the map
    List<V> vertices = new ArrayList<>(resultMap.values());
    // Add all vertices to the graph
    for (V v : vertices) {
        try {
            target.addVertex(v);
        } catch (IllegalArgumentException ignore) {
            // Vertex might already exist, ignore
        }
    }
    // Create a complete bipartite graph by splitting the list in half
    int splitIndex = vertices.size() / 2;
    List<V> left = vertices.subList(0, splitIndex);
    List<V> right = vertices.subList(splitIndex, vertices.size());

    for (V u : left) {
        for (V w : right) {
            try {
                target.addEdge(u, w);
            } catch (IllegalArgumentException ignore) {
                // Edge might already exist, ignore
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        return;
    }
    // Keep a snapshot of the original vertices (right partition)
    Set<V> originalVertices = new HashSet<>(target.vertexSet());
    // Add left partition vertices from the map
    for (V v : resultMap.values()) {
        if (v != null && !target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Now connect every left vertex with every right vertex
    Set<V> leftVertices = new HashSet<>(resultMap.values());
    for (V left : leftVertices) {
        if (left == null) continue;
        for (V right : originalVertices) {
            if (right == null) continue;
            if (!target.containsEdge(left, right) && !target.containsEdge(right, left)) {
                target.addEdge(left, right);
            }
        }
    }
}

