public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Ensure the buffer is empty before encoding.
    buffer.clear();
    // Encode the message into the buffer.  The concrete Schema implementation
    // is expected to provide an encode method that writes into the buffer.
    schema.encode(message, buffer);
    // Retrieve the raw bytes from the buffer.
    byte[] bytes = buffer.toByteArray();
    int size = bytes.length;
    // Prefix the message with its length (big‑endian 4‑byte integer).
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    // Write the actual message bytes.
    out.write(bytes);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(0);
    }
    int rawSize = schema.getSerializedSize(message);
    // Write the size as a variable-length int (varint32)
    int size = rawSize;
    while (size >= 0x80) {
        out.write((byte) ((size & 0x7F) | 0x80));
        size >>>= 7;
    }
    out.write((byte) size);
    // Serialize the message into the buffer
    schema.serialize(message, buffer);
    // Write the serialized bytes
    int len = buffer.position();
    out.write(buffer.get(), 0, len);
    // Reset buffer for future use
    buffer.clear();
    return rawSize;
}

