public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message into the provided LinkedBuffer
    schema.writeTo(buffer, message);
    int size = buffer.getSize();

    // Encode the size as a varint and write it to the output stream
    int tmp = size;
    while ((tmp & ~0x7F) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);

    // Write the serialized message bytes from the buffer to the output stream
    buffer.writeTo(out);
    return size;
}

