    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8)  & 0xFF);
    out.write((size)         & 0xFF);
    // Write the serialized data
    out.write(data);
    // Optionally flush to ensure delivery
    out.flush();
    return size;
}

