public static void createConfigurationDirectory(){
    try {
        String osName = System.getProperty("os.name");
        String osVersion = System.getProperty("os.version");
        File baseDir;
        boolean isWindows2000 = false;
        if (osName != null) {
            osName = osName.trim().toLowerCase(Locale.ENGLISH);
            if (osName.contains("windows") && (osName.contains("2000") || (osVersion != null && osVersion.startsWith("5.0")))) {
                isWindows2000 = true;
            }
        }
        if (isWindows2000) {
            File userHome = new File(System.getProperty("user.home"));
            baseDir = userHome.getParentFile();
            if (baseDir == null) {
                baseDir = userHome; // fallback
            }
        } else {
            baseDir = new File(System.getProperty("user.home"));
        }
        File configDir = new File(baseDir, "lf5");
        if (!configDir.exists() && !configDir.mkdirs()) {
            System.err.println("Failed to create configuration directory: " + configDir.getAbsolutePath());
        }
    } catch (SecurityException se) {
        System.err.println("Security exception while creating configuration directory: " + se.getMessage());
    }
}

