        if (osName.toLowerCase().contains("windows") && osVersion.startsWith("5")) {
            // Windows 2000: create lf5 under Documents and Settings
            File base = new File("C:\\Documents and Settings");
            dir = new File(base, "lf5");
        } else {
            // Other platforms: create lf5 under user.home
