protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Validate inputs
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }
    if (start >= end) {
        return ranges; // Empty list for empty or inverted range
    }
    final long partSize = FETCH_DATA_DURATION; // Expected to be defined elsewhere
    try {
        long current = start;
        while (current < end) {
            long next = Math.min(current + partSize, end);
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception e) {
        // Wrap any unexpected exception
        throw new RuntimeException("Error building time ranges", e);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end) {
        return ranges;
    }
    for (long cur = start; cur <= end; cur += FETCH_DATA_DURATION) {
        long rangeEnd = Math.min(cur + FETCH_DATA_DURATION - 1, end);
        ranges.add(new TimeRange(cur, rangeEnd));
    }
    return ranges;
}

