static long compressTimeBucket(long timeBucket,int dayStep){  
    if (dayStep <= 0) {  
        throw new IllegalArgumentException("dayStep must be positive, got " + dayStep);  
    }  
    long year = timeBucket / 10000;  
    long month = (timeBucket % 10000) / 100;  
    long day = timeBucket % 100;  
    if (day < 1 || day > 31 || month < 1 || month > 12) {  
        throw new IllegalArgumentException("timeBucket has invalid date: " + timeBucket);  
    }  
    long compressedDay = day - ((day - 1) % dayStep);  
    return year * 10000 + month * 100 + compressedDay;  
}

