static long compressTimeBucket(long timeBucket,int dayStep){
    try{
        if(dayStep <= 0) {
            return timeBucket;
        }
        long year = timeBucket / 10000L;
        long monthDay = timeBucket % 10000L;
        int month = (int)(monthDay / 100L);
        int day   = (int)(monthDay % 100L);

        // Basic validation
        if(month < 1 || month > 12 || day < 1) {
            return timeBucket;
        }

        // Determine number of days in the month, accounting for leap years
        int daysInMonth;
        switch(month){
            case 1: case 3: case 5: case 7: case 8: case 10: case 12: daysInMonth = 31; break;
            case 4: case 6: case 9: case 11: daysInMonth = 30; break;
            case 2:
                if((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)){
                    daysInMonth = 29;
                } else {
                    daysInMonth = 28;
                }
                break;
            default: daysInMonth = 30; // fallback, should not occur
        }

        if(day > daysInMonth){
            return timeBucket; // invalid original day
        }

        int newDay = ((day - 1) / dayStep) * dayStep + 1;
        if(newDay > daysInMonth){
            newDay = daysInMonth; // safety clamp
        }

        return year * 10000L + month * 100L + newDay;
    } catch(Exception e){
        // In case of any unexpected error, return the original value
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    int totalLen = str.length();
    if (index < 0 || len < 0 || index > totalLen || index + len > totalLen) {
        throw new IndexOutOfBoundsException("index and len out of bounds");
    }
    int end = index + len;
    int byteCount = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                if (codePoint <= 0x07FF) {
                    byteCount += 2;
                } else if (codePoint <= 0xFFFF) {
                    byteCount += 3;
                } else {
                    byteCount += 4;
                }
                i += 2;
                continue;
            } else {
                // isolated high surrogate
                byteCount += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // isolated low surrogate
            byteCount += 3;
        } else {
            if (ch <= 0x7F) {
                byteCount += 1;
            } else if (ch <= 0x7FF) {
                byteCount += 2;
            } else {
                byteCount += 3;
            }
        }
        i++;
    }
    return byteCount;
}

