    }
    if (index < 0 || len < 0 || index > str.length() || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
            if (i + 1 < end) {
                char ch2 = str.charAt(i + 1);
                if (ch2 >= 0xDC00 && ch2 <= 0xDFFF) { // valid surrogate pair
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    size += 3; // unpaired high surrogate
                }
            } else {
                size += 3; // unpaired high surrogate at end
            }
        } else if (ch >= 0xDC00 && ch <= 0xDFFF) { // unpaired low surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
