private boolean containsAllFields(Fields fields){
    if (fields == null) {
        return false;
    }
    try {
        if (fields instanceof java.util.Map) {
            @SuppressWarnings("unchecked")
            java.util.Map<String, Object> fs = (java.util.Map<String, Object>) fields;
            for (java.util.Map.Entry<String, Object> e : fs.entrySet()) {
                if (!properties.containsKey(e.getKey())) {
                    return false;
                }
                if (!java.util.Objects.equals(properties.get(e.getKey()), e.getValue())) {
                    return false;
                }
            }
            return true;
        } else {
            java.lang.reflect.Field[] declared = fields.getClass().getDeclaredFields();
            for (java.lang.reflect.Field f : declared) {
                f.setAccessible(true);
                Object value = f.get(fields);
                String name = f.getName();
                if (!properties.containsKey(name)) {
                    return false;
                }
                if (!java.util.Objects.equals(properties.get(name), value)) {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception ignored) {
        return false;
    }
}

