public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Assumes LinkedBuffer exposes its internal byte array and the size of valid data
        byte[] data = current.getData();
        int len = current.getSize();
        out.writeInt(len);
        out.write(data, 0, len);
        totalSize += len;
        current = current.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    try {
        Class<?> cls = node.getClass();
        Method getBuffer = cls.getMethod("getBuffer");
        Method getSize = cls.getMethod("getSize");
        Method getNext = cls.getMethod("getNext");
        LinkedBuffer current = node;
        while (current != null) {
            byte[] buf = (byte[]) getBuffer.invoke(current);
            int len = (Integer) getSize.invoke(current);
            out.write(buf, 0, len);
            total += len;
            current = (LinkedBuffer) getNext.invoke(current);
        }
    } catch (Exception e) {
        throw new IOException("Unable to write LinkedBuffer", e);
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
