    }
    if (node == null) {
        return 0;
    }
    int totalBytes = 0;
    for (LinkedBuffer curr = node; curr != null; curr = curr.next) {
        int len = curr.pos; // number of bytes currently stored in this buffer
        out.write(curr.data, 0, len);
        totalBytes += len;
    }
    return totalBytes;
}

