        org.json.JSONWriter writer = new org.json.JSONWriter(sw);
        writer.object();
        Class<?> cls = this.getClass();
        while (cls != null){
            java.lang.reflect.Field[] fields = cls.getDeclaredFields();
            for (java.lang.reflect.Field f: fields){
                f.setAccessible(true);
                writer.key(f.getName()).value(f.get(this));
            }
            cls = cls.getSuperclass();
        }
        writer.endObject();
        return sw.toString();
    }catch (Exception e){
        return "{}";
    }
}

