@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Support for Character and char conversions only
    if (type == Character.class || type == char.class) {
        if (value == null) {
            return null;
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new Exception("String length must be 1 to convert to Character: \"" + s + "\"");
            }
        }
        if (value instanceof Number) {
            // Convert numeric value to char via int representation
            return (char) ((Number) value).intValue();
        }
        throw new Exception("Unsupported value type for Character conversion: " + value.getClass().getName());
    } else {
        throw new Exception("Unsupported target type for conversion: " + type.getName());
    }
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    // Only support Character or char types
    if (!(type.equals(Character.class) || type.equals(char.class))) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    // Null input: return null (no conversion needed)
    if (value == null) {
        return null;
    }
    // If already a Character, return as is
    if (value instanceof Character) {
        return value;
    }
    // String of length 1 -> convert to Character
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return Character.valueOf(s.charAt(0));
        } else {
            throw new IllegalArgumentException("String length must be 1 for conversion to Character");
        }
    }
    // Number -> cast to char based on integer value
    if (value instanceof Number) {
        return Character.valueOf((char)((Number) value).intValue());
    }
    // Unsupported source type
    throw new IllegalArgumentException("Cannot convert from type " + value.getClass().getName() + " to Character");
}

