    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Numeric value out of character range: " + intVal);
        }
        return Character.valueOf((char) intVal);
    }
    if (value instanceof Boolean) {
        return (Boolean) value ? Character.valueOf('1') : Character.valueOf('0');
    }
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        }
        throw new Exception("Cannot convert String to Character: length != 1");
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return Character.valueOf(arr[0]);
        }
        throw new Exception("Cannot convert char[] to Character: length != 1");
    }
    if (value instanceof Character[]) {
        Character[] arr = (Character[]) value;
        if (arr.length == 1) {
            return arr[0];
        }
        throw new Exception("Cannot convert Character[] to Character: length != 1");
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Only convert if the target type is Character or primitive char
    if (type != Character.class && type != char.class) {
        return value;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new Exception("Cannot convert String of length " + str.length() + " to java.lang.Character");
        }
        return str.charAt(0); // auto-boxed to Character
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal; // auto-boxed to Character
    }
    throw new Exception("Unsupported conversion of type " + value.getClass().getName() + " to java.lang.Character");
}

