public static int nextPrime(int desiredCapacity) {
    // Ensure the result is at least 2, the smallest prime
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make sure we start with the next odd number if even (since 2 is already handled)
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        // Check if the candidate is prime
        if (candidate > 1) {
            int sqrtCandidate = (int) Math.sqrt(candidate);
            boolean isPrime = true;
            for (int i = 2; i <= sqrtCandidate; i++) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                return candidate;
            }
        }
        candidate += 2; // Skip even numbers
    }
}

