/**
 * Simple primality test using 6k ± 1 optimization.
 */
private static boolean isPrime(int number) {
    if (number <= 3) {
        return number > 1;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(number);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

