    }
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else {
            for (int i = 2; (long)i * i <= candidate; i++) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
