            throw new IOException("Specified distribution path is not a directory: " + distPath);
        }

        // Load or create a configuration file inside the distribution directory
        File configFile = new File(distDir, "config.properties");
        Properties props = new Properties();

        if (configFile.exists() && configFile.isFile()) {
            try (FileInputStream fis = new FileInputStream(configFile)) {
                props.load(fis);
            }
        } else {
            // Create a default config if none exists
            props.setProperty("defaultKey", "defaultValue");
            try (FileOutputStream fos = new FileOutputStream(configFile)) {
                props.store(fos, "Default configuration");
            }
        }

        // Store the loaded properties into a class field 'configMap' if available
        if (this.getClass().getDeclaredFields() != null) {
            try {
                java.lang.reflect.Field cfgField = this.getClass().getDeclaredField("configMap");
                cfgField.setAccessible(true);
                cfgField.set(this, new HashMap<>(props));
            } catch (NoSuchFieldException e) {
                // The field 'configMap' does not exist; ignore
            }
        }
    } catch (Exception e) {
        System.err.println("Initialization error: " + e.getMessage());
        throw new RuntimeException(e);
    }
}

