protected int removeUnusedNodes(){
    // counter for removed nodes
    int removedCount = 0;
    try {
        // Assume the tree is rooted at a field named 'root'
        if (root == null) {
            return 0;
        }
        // Handle children of the root
        List<Category> rootChildren = root.getChildren();
        if (rootChildren != null) {
            // We'll build a new list of children that remain after pruning
            List<Category> retainedChildren = new ArrayList<>();
            for (Category child : new ArrayList<>(rootChildren)) {
                if (prune(child)) {
                    retainedChildren.add(child);
                }
            }
            // Replace the root's child list with the retained children
            rootChildren.clear();
            rootChildren.addAll(retainedChildren);
        }
    } catch (Exception e) {
        // Log exception if a logger is available, otherwise ignore
        // Example: LOG.error("Error while removing unused nodes", e);
    }
    return removedCount;

    // Helper to prune a subtree; returns true if the node should remain
    boolean prune(Category node) {
        if (node == null) return true;
        List<Category> children = node.getChildren();
        if (children != null) {
            List<Category> retained = new ArrayList<>();
            for (Category child : new ArrayList<>(children)) {
                if (prune(child)) {
                    retained.add(child);
                }
            }
            // Update the node's children list
            children.clear();
            children.addAll(retained);
        }
        if (!node.isActive()) {
            // Node is inactive and will be removed
            removedCount++;
            return false;
        }
        return true;
    }
}

