private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        return null;
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node curr = start;

    if (predicate.test(curr)) {
        return circ;
    }

    while (true) {
        curr = circ.next(); // advance to the next node
        if (curr == null) {
            break;
        }
        if (curr.equals(stop)) {
            break;
        }
        if (predicate.test(curr)) {
            return circ;
        }
    }

    // If no node satisfies predicate, return a circulator positioned at stop
    return new OuterFaceCirculator(stop, dir);
}

