private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false; // Nothing to unlink
    }

    try {
        // If node is the head of the list
        if (node.prev == null) {
            head = node.next;
            if (head != null) {
                head.prev = null;
            }
        } else {
            // Bypass node from previous node
            node.prev.next = node.next;
        }

        // If node is the tail of the list
        if (node.next == null) {
            tail = node.prev;
            if (tail != null) {
                tail.next = null;
            }
        } else {
            // Bypass node from next node
            node.next.prev = node.prev;
        }

        // Clean up the removed node
        node.prev = null;
        node.next = null;
        size--; // Adjust size if the list tracks count
        return true;
    } catch (Exception e) {
        // If any inconsistency occurs, treat as failure
        return false;
    }
}

