private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int size = bounds.size();
    int[] suffixArr = new int[size];
    long sum = 0L;
    for (int i = size - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixArr[i] = (int)sum;
    }
    List<Integer> suffixList = new ArrayList<>(size);
    for (int val : suffixArr) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffixResult = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixResult.add(0);
    }
    long suffixSum = 0L;
    long totalSum = 0L;
    for (Integer val : bounds) {
        totalSum += (val != null ? val : 0);
    }
    for (int i = n - 1; i >= 0; i--) {
        int v = bounds.get(i);
        suffixSum += v;
        suffixResult.set(i, (int) suffixSum);
    }
    return new Pair<>(suffixResult, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    try{
        if (bounds == null){
            throw new IllegalArgumentException("Bounds list cannot be null");
        }
        int n = bounds.size();
        List<Integer> suffixSums = new ArrayList<>(n);
        long totalSum = 0L;
        for (Integer val : bounds){
            if (val == null){
                throw new IllegalArgumentException("Bounds list contains null element");
            }
            totalSum += val;
        }
        long runningSum = 0L;
        for (int i = n - 1; i >= 0; i--){
            runningSum += bounds.get(i);
            // If the running sum exceeds Integer.MAX_VALUE, we clip it to avoid overflow in the list
            suffixSums.add(0, (int)Math.min(runningSum, Integer.MAX_VALUE));
        }
        return new Pair<>(suffixSums, totalSum);
    } catch (Exception e){
        throw new RuntimeException("Error computing suffix sum", e);
    }
}

