public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int n = arr.length;
    if (from < 0 || to >= n || from > to) {
        throw new IndexOutOfBoundsException("Invalid range: from=" + from + ", to=" + to + ", length=" + n);
    }
    while (from < to) {
        V tmp = arr[from];
        arr[from] = arr[to];
        arr[to] = tmp;
        from++;
        to--;
    }
}

