    if (from < 0 || to >= len) {
        throw new IndexOutOfBoundsException("from or to index out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index (" + from + ") greater than to index (" + to + ")");
    }
    int l = from;
    int r = to;
    while (l < r) {
        V tmp = arr[l];
        arr[l] = arr[r];
        arr[r] = tmp;
        l++;
        r--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this || list.isEmpty()) {
        return;
    }
    // Continuously remove the head node from the source list and add it to this list
    while (!list.isEmpty()) {
        ListNode<E> node = list.head;          // current head node of the source list
        list.removeListNode(node);             // atomically detach node from source list
        this.addListNode(node);                // atomically attach node to this list
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Nothing to move if the input list is null, empty, or is this list itself
    if (list == null || list == this || list.isEmpty()){
        return;
    }
    // Traverse the source list and move each node to this list.
    // Capture the next node before removal, because removeListNode may sever
    // the linkage of the node.
    ListNode<E> node = list.head;
    while (node != null){
        ListNode<E> next = node.next;   // preserve next node before removal
        list.removeListNode(node);      // detach from the source list
        this.addListNode(node);         // attach to the destination list
        node = next;                    // move to the next node
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        // Nothing to move if the source list is null
        return;
    }
    try {
        // Lock both lists to ensure the move is atomic with respect to other threads.
        synchronized (this) {
            synchronized (list) {
                // Retrieve the first node from the source list
                ListNodeImpl<E> node = list.getHead();
                // Iterate over the nodes of the source list
                while (node != null) {
                    ListNodeImpl<E> next = node.getNext();
                    // Remove the node from the source list
                    removeListNode(node);
                    // Add the node to this list
                    addListNode(node);
                    // Move to the next node in the source list
                    node = next;
                }
            }
        }
    } catch (Exception e) {
        // If anything goes wrong, wrap and rethrow as an unchecked exception
        throw new RuntimeException("Failed to move list nodes", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Safety checks
    if (list == null || list == this || list.isEmpty()){
        return;
    }
    // Detach nodes from source list
    ListNode<E> sourceHead = list.head;
    ListNode<E> sourceTail = list.tail;
    int movedSize = list.size;

    // Append to this list
    if (this.tail == null){
        // this list is empty
        this.head = sourceHead;
        this.tail = sourceTail;
    } else {
        this.tail.next = sourceHead;
        sourceHead.prev = this.tail;
        this.tail = sourceTail;
    }

    // Update size
    this.size += movedSize;

    // Clear source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) throw new IllegalArgumentException("list cannot be null");
    if (list == this) return;
    ListNodeImpl<E> node = list.head;
    while (node != null) {
        ListNodeImpl<E> next = node.next;
        list.removeListNode(node);
        this.addListNode(node);
        node = next;
    }
}

