    if(buf == null){
        throw new IllegalArgumentException("buf must not be null");
    }
    // Assume the class has a field 'name' holding the full name
    String name = this.name;
    if(name == null || name.isEmpty()){
        return; // nothing to abbreviate
    }
    if(nameStart < 0 || nameStart > name.length()){
        throw new IndexOutOfBoundsException("nameStart out of bounds");
    }
    int lastDot = name.lastIndexOf('.', name.length() - 1);
    if(lastDot < nameStart){
        // No dot after the start index – simply append the rest of the name
        buf.append(name.substring(nameStart));
        return;
    }
    // Append abbreviated form:
    // first character of each component before the last dot,
    // then the full final component.
    int i = nameStart;
    while(i < lastDot){
        if(name.charAt(i) == '.'){
            i++;            // skip dot
            continue;
        }
        buf.append(name.charAt(i)); // first char of component
        i = name.indexOf('.', i);   // move to next dot
        if(i == -1){
            break;
        }
    }
    // Append the final component in full
    buf.append(name.substring(lastDot));
}

