    if (nameStart < 0 || nameStart > buf.length()) return; // invalid start index
    if (nameStart == buf.length()) return; // nothing beyond
    String name = buf.substring(nameStart);
    // Find the last dot to determine the final component
    int lastDot = name.lastIndexOf('.');
    String lastSegment = (lastDot >= 0) ? name.substring(lastDot + 1) : name;
    StringBuilder abbreviated = new StringBuilder();
    int i = 0;
    while (i < name.length()) {
        int dot = name.indexOf('.', i);
        if (dot == -1) {
            // last component – keep it whole
            abbreviated.append(name.substring(i));
            break;
        } else {
            // component before dot
            if (dot != i) { // skip empty segments
                // if this component is not the last, keep only its first char
                if (dot < name.length() - 1) {
