                    abbreviated.append(name.substring(i, dot + 1));
                }
            }
            i = dot + 1;
        }
    }
    // Replace the part of the buffer from nameStart onward with the abbreviation
    buf.replace(nameStart, buf.length(), abbreviated.toString());
