        java.util.Collections.sort(sorted);

        // Build map from key to its maximum lower bound (previous element in sorted order)
        java.util.Map<Integer, Integer> lowerBoundMap = new java.util.HashMap<>();
        Integer prev = null;
        for (Integer v : sorted) {
            lowerBoundMap.put(v, prev);
            prev = v;
        }

        // Preserve original order in output
        for (K k : keys) {
            bounds.add(lowerBoundMap.get((Integer) k));
        }
    } catch (Exception e) {
        // In case of any unexpected issue, return an empty list
        return new ArrayList<>();
    }
    return bounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int len = descriptor.length();
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            i = 1; // skip '('
            while (i < len && descriptor.charAt(i) != ')') {
                char c = descriptor.charAt(i);
                int slots = 1;

                // consume array brackets
                while (c == '[') {
                    i++;
                    if (i >= len) {
                        throw new IllegalArgumentException("Malformed descriptor");
                    }
                    c = descriptor.charAt(i);
                }

                if (c == 'J' || c == 'D') { // long or double
                    slots = 2;
                } else if (c == 'L') { // object type
                    // consume until ';'
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= len) {
                        throw new IllegalArgumentException("Malformed descriptor");
                    }
                }

                i++; // move past current type
                for (int s = 0; s < slots; s++) {
                    outputStack.pop(); // assume a stack field named outputStack
                }
            }
        } else {
            char c = descriptor.charAt(i);
            int slots = 1;

            while (c == '[') {
                i++;
                if (i >= len) {
                    throw new IllegalArgumentException("Malformed descriptor");
                }
                c = descriptor.charAt(i);
            }

            if (c == 'J' || c == 'D') {
                slots = 2;
            } else if (c == 'L') {
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Malformed descriptor");
                }
            }

            i++; // move past type
            for (int s = 0; s < slots; s++) {
                outputStack.pop();
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

