    if (descriptor == null || descriptor.isEmpty()) return;
    int pos = 0;
    try {
        if (descriptor.charAt(pos) == '(') {
            pos++; // skip '('
            while (descriptor.charAt(pos) != ')') {
                char c = descriptor.charAt(pos);
