    List<Integer> upperBounds = new ArrayList<>(keys.size());
    if (keys == null || keys.isEmpty()){
        return upperBounds;
    }
    for (int i = 0; i < keys.size(); i++){
        K key = keys.get(i);
        int bound = keys.size(); // default: no upper bound found
        try{
            if (!(key instanceof Comparable)){
                // Non-comparable key: cannot compute bounds
                throw new IllegalArgumentException("List element at index " + i + " is not Comparable");
            }
            @SuppressWarnings("unchecked")
            Comparable<? super K> compKey = (Comparable<? super K>) key;
            for (int j = i + 1; j < keys.size(); j++){
                K other = keys.get(j);
                if (!(other instanceof Comparable)){
                    throw new IllegalArgumentException("List element at index " + j + " is not Comparable");
                }
                @SuppressWarnings("unchecked")
                Comparable<? super K> compOther = (Comparable<? super K>) other;
                if (compOther.compareTo(key) > 0) {
                    bound = j;
                    break; // first greater found (upper bound)
                }
            }
        } catch (ClassCastException e){
            // If a comparison fails due to incompatible types, treat as no bound
            bound = keys.size();
        }
        upperBounds.add(bound);
    }
    return upperBounds;
}

