public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder encoded = new StringBuilder(s.length() * 3); // worst case each char replaced by 3 chars
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        switch (c) {
            case '{':
                encoded.append("%7B");
                break;
            case '}':
                encoded.append("%7D");
                break;
            default:
                encoded.append(c);
                break;
        }
    }
    return encoded.toString();
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    return s.replace("{", "%7B").replace("}", "%7D");
}

public static boolean equals(Point2D p1, Point2D p2) {
    if (p1 == p2) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    final double tol = 1e-9;
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();
    return Math.abs(dx) <= tol && Math.abs(dy) <= tol;
}

