public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    String base = path.replace('\\', '/');
    int lastSep = base.lastIndexOf('/');
    if (lastSep >= 0) {
        base = base.substring(0, lastSep + 1);
    } else {
        base = "";
    }
    String combined = base + relativePath;
    String[] parts = combined.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    java.util.StringJoiner joiner = new java.util.StringJoiner("/");
    for (String s : stack) {
        joiner.add(s);
    }
    String result = joiner.toString();
    if (base.startsWith("/")) {
        result = "/" + result;
    }
    if (result.isEmpty()) {
        result = ".";
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    try {
        java.io.File base = new java.io.File(path);
        java.io.File combined = new java.io.File(base, relativePath);
        return combined.getCanonicalPath();
    } catch (java.io.IOException e) {
        // If resolution fails, fall back to returning the original base path.
        return path;
    }
}

public static String applyRelativePath(String path,String relativePath){
    if (path==null || relativePath==null){
        return (path==null)?relativePath: path;
    }
    try{
        boolean isAbsolute = path.startsWith("/");
        java.util.List<String> parts = new java.util.ArrayList<>();
        for (String seg : path.split("/")){
            if (seg.isEmpty() || seg.equals(".")) continue;
            if (seg.equals("..")){
                if (!parts.isEmpty()){
                    parts.remove(parts.size()-1);
                }
            }else{
                parts.add(seg);
            }
        }
        for (String seg : relativePath.split("/")){
            if (seg.isEmpty() || seg.equals(".")) continue;
            if (seg.equals("..")){
                if (!parts.isEmpty()){
                    parts.remove(parts.size()-1);
                }
            }else{
                parts.add(seg);
            }
        }
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        if (isAbsolute){
            sb.append("/");
        }
        for (int i=0;i<parts.size();i++){
            sb.append(parts.get(i));
            if (i < parts.size()-1){
                sb.append("/");
            }
        }
        return sb.toString();
    }catch (Exception e){
        return null;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Normalise separators to '/'
    String normPath = path.replace('\\', '/');
    String normRelative = relativePath.replace('\\', '/');
    // Remove leading separators from relativePath (treat as truly relative)
    normRelative = normRelative.replaceAll("^[/]+", "");
    if (normRelative.isEmpty()) {
        return normPath.replace('\\', '/');
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(normPath);
        java.nio.file.Path rel = java.nio.file.Paths.get(normRelative);
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        return resolved.toString().replace(java.io.File.separatorChar, '/');
    } catch (Exception e) {
        // Fallback simple concatenation if the path library fails
        if (normPath.endsWith("/")) {
            return (normPath + normRelative).replace('\\', '/');
        } else {
            return (normPath + "/" + normRelative).replace('\\', '/');
        }
    }
}

public static String applyRelativePath(String path, String relativePath){
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        java.io.File file = new java.io.File(path, relativePath);
        java.nio.file.Path normalizedPath = file.toPath().normalize();
        String result = normalizedPath.toString();
        // Convert platform-specific separator to '/' if necessary
        if (!java.io.File.separator.equals("/")) {
            result = result.replace(java.io.File.separatorChar, '/');
        }
        return result;
    } catch (SecurityException e) {
        throw new RuntimeException("Unable to resolve path", e);
    }
}

