static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        if (array instanceof String[]) {
            return (String[]) array;
        } else {
            String[] result = new String[nonNullCount];
            for (int i = 0; i < nonNullCount; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    } else {
        String[] result = new String[nonNullCount];
        int idx = 0;
        for (Object o : array) {
            if (o != null) {
                result[idx++] = (String) o;
            }
        }
        return result;
    }
}

