protected void append(LoggingEvent event){
    if (event == null) return;
    String msg = event.getRenderedMessage();
    if (clients == null) return;
    for (Object client : clients) {
        try {
            if (client instanceof java.io.PrintWriter) {
                java.io.PrintWriter writer = (java.io.PrintWriter) client;
                writer.println(msg);
                writer.flush();
            } else if (client instanceof java.io.OutputStream) {
                java.io.OutputStream out = (java.io.OutputStream) client;
                out.write(msg.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                out.flush();
            } else if (client instanceof java.io.Writer) {
                java.io.Writer writer = (java.io.Writer) client;
                writer.write(msg);
                writer.flush();
            } else {
                // Fallback: if the client has a 'write' method
                java.lang.reflect.Method m = client.getClass().getMethod("write", String.class);
                m.invoke(client, msg);
            }
        } catch (Exception e) {
            // Log or ignore the exception to prevent a single client failure from
            // interrupting the rest of the notification process.
            // Assuming a logger named LOG is available.
            if (LOG != null) {
                LOG.warn("Failed to write log message to client: {}", client, e);
            }
        }
    }
}

