public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (shift < 32) {
        int b = in.read();
        if (b == -1) {
            return 0; // reached EOF, conventionally tag 0 indicates end
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint32");
}

public int readTag() throws IOException {
    try {
        int result = 0;
        int shift = 0;
        while (shift < 32) {
            int b = input.read();
            if (b == -1) {
                if (shift == 0) {
                    // EOF before any bytes were read – signal end of message
                    return 0;
                }
                throw new EOFException("EOF while reading tag");
            }
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
            shift += 7;
        }
        throw new IOException("Malformed varint");
    } catch (EOFException e) {
        return 0;
    }
}

